INSERT INTO faq (position, data) VALUES
  (0, '{"q": "Сколько стоит дом под ключ?", "q_ky": "Ачкычка чейин үй канча турат?", "a": "{price} за м². В цену входит всё из раздела «Под ключ»: архитектурный проект, фундамент, несущий металлический каркас, утепление, кровля, фасад, окна и двери, отделка, сантехника, электрика, оснащение санузла и тёплые полы. Точную смету считаем бесплатно под ваш проект и участок.", "a_ky": "1 м² үчүн — {price}. Баага «Ачкычка чейин» бөлүмүндөгүнүн баары кирет: архитектуралык долбоор, пайдубал, көтөрүүчү металл каркас, жылуулоо, чатыр, фасад, терезе жана эшиктер, жасалга, сантехника, электр, ванна бөлмөсүнүн жабдуулары жана жылуу пол. Так сметаны долбооруңузга жана жер тилкеңизге жараша акысыз эсептеп беребиз."}'),
  (1, '{"q": "Сколько времени занимает стройка?", "q_ky": "Курулуш канча убакыт алат?", "a": "В среднем {months} от фундамента до ключей, самые быстрые дома — от {months_min}. Точный срок фиксируем в договоре.", "a_ky": "Пайдубалдан ачкычка чейин орточо {months}, эң тез курулган үйлөр — {months_min} баштап. Так мөөнөттү келишимде бекитебиз."}'),
  (2, '{"q": "Можно ли строить зимой?", "q_ky": "Кышында курууга болобу?", "a": "Да, мы строим в любое время года. Не нужно ждать весны — можно начать, как только готов проект.", "a_ky": "Ооба, биз жылдын каалаган мезгилинде курабыз. Жазды күтүүнүн кереги жок — долбоор даяр болгондо эле баштаса болот."}'),
  (3, '{"q": "В каких регионах вы строите?", "q_ky": "Кайсы аймактарда курасыздар?", "a": "По всему Кыргызстану: Бишкек и Чуйская область, Иссык-Куль, Нарын, Талас, Ош, Джалал-Абад и Баткен.", "a_ky": "Бүт Кыргызстан боюнча: Бишкек жана Чүй облусу, Ысык-Көл, Нарын, Талас, Ош, Жалал-Абад жана Баткен."}'),
  (4, '{"q": "Можно изменить готовый проект или сделать свой?", "q_ky": "Даяр долбоорду өзгөртсө же өзүбүздүкүн жасаса болобу?", "a": "Да. Любой типовой проект можно доработать — добавить спальню, террасу, поменять окна. Или спроектируем дом с нуля под ваш участок и образ жизни; эскизный проект — в подарок.", "a_ky": "Ооба. Каалаган типтүү долбоорду өркүндөтсө болот — уктоочу бөлмө, терраса кошуу, терезелерди алмаштыруу. Же үйдү жер тилкеңизге жана жашоо образыңызга ылайык нөлдөн долбоорлойбуз; эскиздик долбоор — белекке."}'),
  (5, '{"q": "Не будет ли холодно зимой?", "q_ky": "Кышында суук болбойбу?", "a": "Стены, пол и кровля утеплены двухслойным базальтом плотностью 70: зимой тепло, летом прохладно. Плюс тёплые полы — их мы дарим.", "a_ky": "Дубал, пол жана чатыр тыгыздыгы 70 болгон эки катмар базальт менен жылуулатылат: кышында жылуу, жайында салкын. Анын үстүнө жылуу пол — аны белекке беребиз."}'),
  (6, '{"q": "Какой фундамент вы делаете?", "q_ky": "Кандай пайдубал жасайсыздар?", "a": "Бетонные сваи или ленточный фундамент — выбираем после оценки вашего грунта.", "a_ky": "Бетон казыктар же тасмалуу пайдубал — топурагыңызды баалагандан кийин тандайбыз."}'),
  (7, '{"q": "Почему каркас из металла, а не из дерева?", "q_ky": "Эмне үчүн каркас жыгачтан эмес, металлдан?", "a": "Металл не даёт усадки, не гниёт и не ведёт геометрию: стены остаются ровными, окна и двери не перекашивает, а отделку можно делать сразу, без ожидания усадки. Дерево мы оставляем там, где оно лучше всего, — в отделке, на фасаде и террасе.", "a_ky": "Металл отурбайт, чирибейт жана геометриясы бузулбайт: дубалдар түз бойдон калат, терезе-эшиктер кыйшайбайт, ал эми жасалганы отурушун күтпөй эле дароо баштаса болот. Жыгачты эң жакшы иштеген жерде калтырабыз — жасалгада, фасадда жана террасада."}'),
  (8, '{"q": "Какая гарантия?", "q_ky": "Кепилдик кандай?", "a": "Официальная гарантия на дом — {warranty}. Несущий каркас всегда из металла: дом не «смещается» и служит более 40 лет.", "a_ky": "Үйгө расмий кепилдик — {warranty}. Көтөрүүчү каркас дайыма металлдан: үй «жылбайт» жана 40 жылдан ашык кызмат кылат."}'),
  (9, '{"q": "Что за подарок и как его получить?", "q_ky": "Кандай белек жана аны кантип алса болот?", "a": "Эскизный проект и тёплый пол — для всех, кто заказывает строительство под ключ, без ограничения по сроку. Просто оставьте заявку.", "a_ky": "Эскиздик долбоор жана жылуу пол — ачкычка чейин курулушка буйрутма бергендердин баарына, мөөнөт чектөөсүз. Жөн гана арыз калтырыңыз."}');
