-- Частые вопросы на главной, редактируются в админке. data: q / q_ky — вопрос, a / a_ky — ответ.
-- В ответе можно писать {price}, {months}, {months_min}, {warranty} — сайт подставит значения из вкладки «Основное».
-- Начальные записи — вопросы, которые были в вёрстке.
CREATE TABLE faq (
  id         serial PRIMARY KEY,
  position   integer NOT NULL DEFAULT 0,
  data       jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by text
);
